contracts/BaseFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.21;

import "./BaseFactoryToken.sol";

contract BaseFactory {

    event ERC721TokenCreated(address contractAddress);

    function deployNewERC721Token(string memory name, string memory symbol, string memory image, uint256 supply, uint256 mintPrice) public returns (address) {
        BaseFactoryToken t = new BaseFactoryToken(name, symbol, image, supply, mintPrice);
        emit ERC721TokenCreated(address(t));
        t.transferOwnership(msg.sender);
        return address(t);
    }

}

